#include <stdio.h>
#include <string.h>
#include <stdlib.h>

typedef struct {
    int num;   // 1-9
    char col;  // 'R', 'G', 'B', 'W'
} Card;

// Compare function for sorting cards by number then color
int cmp(const void *a, const void *b) {
    Card *ca = (Card *)a;
    Card *cb = (Card *)b;
    if (ca->num != cb->num)
        return ca->num - cb->num;
    return ca->col - cb->col;
}

// Check if three cards form a valid set (same number or sequential)
int is_valid_set(Card c1, Card c2, Card c3) {
    // Must be same color
    if (c1.col != c2.col || c2.col != c3.col)
        return 0;
    // Same number
    if (c1.num == c2.num && c2.num == c3.num)
        return 1;
    // Sequential (sorted order assumed: c1.num <= c2.num <= c3.num)
    if (c1.num + 1 == c2.num && c2.num + 1 == c3.num)
        return 1;
    return 0;
}

// Try all partitions of 9 cards into 3 groups of 3
int can_win(Card *hand) {
    // Generate all combinations of 3 cards for first set
    for (int i = 0; i < 7; i++) {
        for (int j = i+1; j < 8; j++) {
            for (int k = j+1; k < 9; k++) {
                Card set1[3] = {hand[i], hand[j], hand[k]};
                if (!is_valid_set(set1[0], set1[1], set1[2]))
                    continue;
                // Remaining 6 cards
                Card rem[6];
                int idx = 0;
                for (int m = 0; m < 9; m++) {
                    if (m != i && m != j && m != k)
                        rem[idx++] = hand[m];
                }
                // Try all combinations for second set from remaining
                for (int a = 0; a < 4; a++) {
                    for (int b = a+1; b < 5; b++) {
                        for (int c = b+1; c < 6; c++) {
                            Card set2[3] = {rem[a], rem[b], rem[c]};
                            if (!is_valid_set(set2[0], set2[1], set2[2]))
                                continue;
                            // Last 3 cards automatically form set3
                            Card set3[3];
                            int idx2 = 0;
                            for (int m = 0; m < 6; m++) {
                                if (m != a && m != b && m != c)
                                    set3[idx2++] = rem[m];
                            }
                            if (is_valid_set(set3[0], set3[1], set3[2]))
                                return 1;
                        }
                    }
                }
            }
        }
    }
    return 0;
}

