        if (count == 3) {
            // All cards used
            for (boolean u : used) if (!u) return false;
            return true;
        }

        // Find first unused card
        int first = -1;
        for (int i = start; i < 9; i++) {
            if (!used[i]) {
                first = i;
                break;
            }
        }
        if (first == -1) return false;

        used[first] = true;
        // Try to pair with two other unused cards
        for (int j = first + 1; j < 9; j++) {
            if (used[j]) continue;
            for (int k = j + 1; k < 9; k++) {
                if (used[k]) continue;
                if (isValidSet(cards[first], cards[j], cards[k])) {
                    used[j] = true;
                    used[k] = true;
                    if (dfs(cards, used, first + 1, count + 1)) {
                        return true;
                    }
                    used[j] = false;
                    used[k] = false;
                }
            }
        }
        used[first] = false;
        return false;
