public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int[][] cnt = new int[4][10];

    static int colorIndex(char c) {
        if (c == 'R') return 0;
        if (c == 'G') return 1;
        if (c == 'B') return 2;
        return 3; // Y
    }

    static boolean canWin() {
        return dfs(0);
    }

    static boolean dfs(int formed) {
        if (formed == 3) {
            for (int c = 0; c < 4; c++) {
                for (int n = 1; n <= 9; n++) {
                    if (cnt[c][n] != 0) return false;
                }
            }
            return true;
        }

        int sc = -1, sn = -1;
        outer:
        for (int c = 0; c < 4; c++) {
            for (int n = 1; n <= 9; n++) {
                if (cnt[c][n] > 0) {
                    sc = c;
                    sn = n;
                    break outer;
                }
            }
        }

        if (sc == -1) return formed == 3;

        // Try same number triple
        if (cnt[sc][sn] >= 3) {
            cnt[sc][sn] -= 3;
            if (dfs(formed + 1)) return true;
            cnt[sc][sn] += 3;
        }

        // Try consecutive triple
        if (sn <= 7 && cnt[sc][sn] > 0 && cnt[sc][sn + 1] > 0 && cnt[sc][sn + 2] > 0) {
            cnt[sc][sn]--;
            cnt[sc][sn + 1]--;
            cnt[sc][sn + 2]--;
            if (dfs(formed + 1)) return true;
            cnt[sc][sn]++;
            cnt[sc][sn + 1]++;
            cnt[sc][sn + 2]++;
        }

        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;

        int T = Integer.parseInt(first);
        StringBuilder out = new StringBuilder();

        for (int tc = 0; tc < T; tc++) {
            for (int i = 0; i < 4; i++) Arrays.fill(cnt[i], 0);

            for (int i = 0; i < 9; i++) {
                String s = fs.next();
                int len = s.length();
                char color = s.charAt(len - 1);
                int num = Integer.parseInt(s.substring(0, len - 1));
                cnt[colorIndex(color)][num]++;
            }

            out.append(canWin() ? "Win" : "Continue");
            if (tc + 1 < T) out.append('\n');
        }

        System.out.print(out.toString());
    }
}

