import sys
from collections import defaultdict

def can_win(cards):
    # cards: list of (number, color), length 9
    by_color = defaultdict(list)
    for num, col in cards:
        by_color[col].append(num)

    # For each color, count occurrences of numbers 1..9
    color_counts = {}
    for c, nums in by_color.items():
        cnt = [0] * 10
        for x in nums:
            cnt[x] += 1
        color_counts[c] = cnt

    colors = list(color_counts.keys())

    def solve_color(cnt, k):
        # Can this color's multiset be partitioned into exactly k groups,
        # each group either triplet same number or consecutive run of length 3?
        total = sum(cnt)
        if total != 3 * k:
            return False

        memo = {}

        def dfs(state):
            if state in memo:
                return memo[state]
            if sum(state) == 0:
                memo[state] = True
                return True

            # find smallest existing number
            i = 1
            while i <= 9 and state[i] == 0:
                i += 1

            lst = list(state)

            # Try triplet
            if lst[i] >= 3:
                lst[i] -= 3
                if dfs(tuple(lst)):
                    memo[state] = True
                    return True
                lst[i] += 3

            # Try sequence
            if i <= 7 and lst[i] >= 1 and lst[i+1] >= 1 and lst[i+2] >= 1:
                lst[i] -= 1
                lst[i+1] -= 1
                lst[i+2] -= 1
                if dfs(tuple(lst)):
                    memo[state] = True
                    return True

            memo[state] = False
            return False

        return dfs(tuple(cnt))

    # Distribute 3 total sets among colors.
    # Since each set uses one color only, each color must contribute count/3 sets.
    total_sets = 0
    for c in colors:
        total = sum(color_counts[c])
        if total % 3 != 0:
            return False
        total_sets += total // 3
    if total_sets != 3:
        return False

    for c in colors:
        k = sum(color_counts[c]) // 3
        if not solve_color(color_counts[c], k):
            return False
    return True


